#include "../../fpga_descriptor_front/descriptor/packed.hpp"
#include "adapter.hpp"
#include <iostream>
int main(int argc,char**argv){try{Graph g(argv[1]);dfdesc::Admission a(g);dfdesc::Image image(g,0,a);auto need=[](bool x){if(!x)throw std::runtime_error("ADDRESS_ABI_AUDIT");};uint64_t labels=Graph::align(image.layout.end_bytes/32),n=(g.w.h.nodes+3)/4,scratch=Graph::align(labels+n),output=Graph::align(scratch+n),stride=Graph::align((g.w.h.cells+3)/4),cost=Graph::align(output+g.w.h.jobs*stride);
 for(auto base:{g.rowbase,g.edgebase,g.metabase,image.base_line,labels,scratch,output,cost})need(base%32==0);
 need(cost+(g.w.h.costs+3)/4<=0x100000000ull);uint64_t checked=0;
 for(unsigned q=0;q<g.w.h.jobs;++q){need((output+q*stride)%32==0);for(uint64_t node=0;node<g.w.h.nodes;++node){uint64_t line=node/4;unsigned bank=2*(line&31)+((line>>5)&1),port=bank/2;need(((labels+line)&31)==port&&((scratch+line)&31)==port);need(lf::legal(48+bank,4,labels+line)&&lf::legal(112+bank,8,scratch+line));need(image.layout.line(q,node)<=UINT32_MAX);need(g.rowbase+node/4+(node%4==3)<=UINT32_MAX);need(g.metabase+q*g.metastride+node/4<=UINT32_MAX);if(g.row[node]<g.row[node+1])need(g.edgebase+(g.row[node+1]-1)/8<=UINT32_MAX);++checked;}}
 for(unsigned s=0;s<208;++s)for(unsigned k=0;k<12;++k)for(uint32_t id:{0u,255u,65535u,0xffffffffu})for(uint32_t gen:{0u,255u,65535u,0xffffffffu}){unsigned p=s<48?31:s<112?(s-48)/2:s<176?(s-112)/2:s-176;uint64_t line=0xffffffe0ull+p;if(lf::legal(s,k,line)){auto x=lf::pack(s,k,id,gen);need(lf::unpack_source(x,p)==s&&uint32_t(x.lo)==id&&uint32_t(x.lo>>32)==gen&&(x.hi&15)==k);}need(!lf::legal(s,k,0x100000000ull));if(s>=48)need(!lf::legal(s,k,(line&~31ull)|((p+1)%32)));}
 std::cout<<"{\"status\":\"PASS\",\"jobs\":"<<g.w.h.jobs<<",\"nodes\":"<<g.w.h.nodes<<",\"sample_node_checks\":"<<checked<<",\"format_bytes\":"<<a.formatbytes<<",\"row_base_line\":"<<g.rowbase<<",\"edge_base_line\":"<<g.edgebase<<",\"meta_base_line\":"<<g.metabase<<",\"descriptor_base_line\":"<<image.base_line<<",\"label_base_line\":"<<labels<<",\"scratch_base_line\":"<<scratch<<",\"output_base_line\":"<<output<<",\"output_stride_lines\":"<<stride<<",\"cost_base_line\":"<<cost<<",\"maximum_line\":"<<cost+(g.w.h.costs+3)/4-1<<",\"identity_id_bits\":32,\"identity_generation_bits\":32,\"negative_overflow_owner_checks\":true}\n";
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
